import type { Config } from 'tailwindcss'

/**
 * Colors, radius and fonts are CSS variables so the admin panel can restyle
 * the whole site at runtime (Admin > Settings > Theme / Typography).
 * The variables themselves are generated by composables/useTheme.ts.
 */
const brandShades = ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900']
const inkShades = ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900']
const accentShades = ['50', '100', '200', '300', '400', '500', '600', '700', '800', '900']

export default <Partial<Config>>{
  // Class/attribute based dark mode: the runtime theme engine toggles
  // <html data-mode="dark"> (composables/useTheme.ts), so components can use
  // `dark:` variants instead of hardcoding light-only colors.
  darkMode: ['selector', '[data-mode="dark"]'],
  content: [
    './app.vue',
    './components/**/*.{vue,js,ts}',
    './layouts/**/*.vue',
    './pages/**/*.vue',
    './composables/**/*.{js,ts}',
    './plugins/**/*.{js,ts}'
  ],
  theme: {
    extend: {
      fontFamily: {
        sans: ['var(--font-body)', 'Inter', 'ui-sans-serif', 'system-ui', 'sans-serif'],
        heading: ['var(--font-heading)', 'Inter', 'ui-sans-serif', 'system-ui', 'sans-serif']
      },
      colors: {
        transparent: 'transparent',
        white: '#ffffff',
        surface: 'rgb(var(--c-surface) / <alpha-value>)',
        page: 'rgb(var(--c-bg) / <alpha-value>)',
        inverse: 'rgb(var(--c-inverse-bg) / <alpha-value>)',
        brand: Object.fromEntries(brandShades.map((s) => [s, `rgb(var(--brand-${s}) / <alpha-value>)`])),
        ink: Object.fromEntries(inkShades.map((s) => [s, `rgb(var(--ink-${s}) / <alpha-value>)`])),
        accent: Object.fromEntries(accentShades.map((s) => [s, `rgb(var(--accent-${s}) / <alpha-value>)`]))
      },
      boxShadow: {
        card: '0 1px 2px rgba(15,23,42,.06), 0 4px 16px rgba(15,23,42,.06)',
        pop: '0 8px 30px rgba(234,88,12,.18)'
      },
      borderRadius: {
        sm: 'var(--radius-sm)',
        md: 'var(--radius-md)',
        lg: 'var(--radius-lg)',
        xl: 'var(--radius-xl)',
        '2xl': 'var(--radius-2xl)',
        '3xl': 'var(--radius-3xl)'
      }
    }
  }
}
